#' Set Intersections (Python Core)
#'
#' 
#' @param data .
#' @param var1 .
#' @param var2 .
#' @param var3 .
#' @param var4 .
#' @param var1true .
#' @param var2true .
#' @param var3true .
#' @param var4true .
#' @param patternOrder .
#' @param showZero .
#' @param showMembershipTable .
#' @param interactive .
#' @param showSetMatrix .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$sets} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$intersections} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$membershipTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$intersectionPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$intersectionMatrix} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$membershipGroups} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$sets$asDF}
#'
#' \code{as.data.frame(results$sets)}
#'
#' @export
pyvenn <- function(
    data,
    var1 = NULL,
    var2 = NULL,
    var3 = NULL,
    var4 = NULL,
    var1true,
    var2true,
    var3true,
    var4true,
    patternOrder = "membership",
    showZero = FALSE,
    showMembershipTable = FALSE,
    interactive = TRUE,
    showSetMatrix = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyvenn requires jmvcore to be installed (restart may be required)")

    if ( ! missing(var1)) var1 <- jmvcore::resolveQuo(jmvcore::enquo(var1))
    if ( ! missing(var2)) var2 <- jmvcore::resolveQuo(jmvcore::enquo(var2))
    if ( ! missing(var3)) var3 <- jmvcore::resolveQuo(jmvcore::enquo(var3))
    if ( ! missing(var4)) var4 <- jmvcore::resolveQuo(jmvcore::enquo(var4))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(var1), var1, NULL),
            `if`( ! missing(var2), var2, NULL),
            `if`( ! missing(var3), var3, NULL),
            `if`( ! missing(var4), var4, NULL))

    for (v in var1) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in var2) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in var3) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in var4) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyvennOptions$new(
        var1 = var1,
        var2 = var2,
        var3 = var3,
        var4 = var4,
        var1true = var1true,
        var2true = var2true,
        var3true = var3true,
        var4true = var4true,
        patternOrder = patternOrder,
        showZero = showZero,
        showMembershipTable = showMembershipTable,
        interactive = interactive,
        showSetMatrix = showSetMatrix,
        showConsole = showConsole)

    analysis <- pyvennClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

